from saleor.product.models import ProductMedia
from saleor.product import tasks as product_tasks


def make_response(status_code=200, content_type="image/png", content=b"data"):
    resp = mock.MagicMock()
    resp.status_code = status_code
    resp.headers = {"content-type": content_type}
    resp.content = content
    return resp


@contextmanager
def cm(resp):
    yield resp


def valid_png_bytes():
    buf = BytesIO()
    Image.new("RGB", (2, 2), "red").save(buf, format="PNG")
    return buf.getvalue()


@pytest.fixture
def media(product):
    return ProductMedia.objects.create(
        product=product,
        external_url="https://example.com/img.png",
        type=ProductMediaTypes.IMAGE,
    )


def test_success(media, media_root):
    resp = make_response(content=valid_png_bytes())
    with mock.patch.object(product_tasks.HTTPClient, "send_request", return_value=cm(resp)):
        product_tasks.fetch_product_media_image_task(media.pk)
    media.refresh_from_db()
    assert media.image
    assert media.external_url is None


def test_missing_pk_ok():
    product_tasks.fetch_product_media_image_task(99999999)


def test_already_has_image(media, media_root):
